/**
 * The local pre-check must agree with the contract, case for case.
 *
 * `test-vectors/policies.json` is generated by the Rust side and carries one valid policy and
 * eight invalid ones, each with the error code the contract panics with. A pre-check that
 * disagreed would be worse than none: it would either send doomed transactions or refuse
 * policies the chain would have accepted.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

import { CanonicalError, canonical, sha256Hex } from "../src/canonical.js";
import {
  groupForSource,
  minKForNonZero,
  precheckPolicyJson,
  serializePolicy,
  sizeMultiplierBps,
  validatePolicy,
  type EvidenceBlock,
  type Policy,
} from "../src/policy.js";

const VECTORS = join(import.meta.dirname, "..", "..", "..", "test-vectors");

const vec = JSON.parse(readFileSync(join(VECTORS, "policies.json"), "utf8")) as {
  valid: { policyJson: string; policyHash: string };
  invalid: { name: string; policyJson: string; error: string; why: string }[];
};

const DESK = "yk-desk";

describe("pre-check against the contract's own vectors", () => {
  it("accepts the valid policy and returns the same hash the contract stored", () => {
    const policy = precheckPolicyJson(vec.valid.policyJson, DESK);
    expect(policy.deskId).toBe(DESK);
    expect(sha256Hex(vec.valid.policyJson)).toBe(vec.valid.policyHash);
  });

  for (const c of vec.invalid) {
    it(`refuses ${c.name} with ${c.error} (${c.why})`, () => {
      let thrown: unknown;
      try {
        precheckPolicyJson(c.policyJson, DESK);
      } catch (e) {
        thrown = e;
      }
      expect(thrown, "the pre-check must refuse what the contract refuses").toBeInstanceOf(
        CanonicalError,
      );
      expect((thrown as CanonicalError).code).toBe(c.error);
    });
  }
});

describe("serializePolicy", () => {
  const base: Policy = {
    schema: "krexa.ual.policy/1",
    deskId: "ebi",
    maxPositionUsd: "1000000000",
    maxOpenPositions: 3,
    dailyLossLimitUsd: "200000000",
    allowedAssets: ["BTC", "ETH"],
    allowedVenues: ["hyperliquid", "paper"],
    slippageCapBps: 30,
    allowedModes: ["paper"],
    killSwitch: { autoOnDailyLoss: true, monitorMayEngage: true },
    evidence: {
      required: true,
      maxAgeSec: 900,
      groups: [
        { group: "exchange-hl", sources: ["hyperliquid"] },
        { group: "newswire-a", sources: ["newswire-a.example"] },
      ],
      sizeTableBps: [0, 0, 5000, 10000],
      verifierCodeHash: "a".repeat(64),
    },
  };

  it("produces bytes that are their own canonical form", () => {
    const bytes = serializePolicy(base);
    expect(canonical(JSON.parse(bytes))).toBe(bytes);
  });

  it("does not depend on the key order of the input object", () => {
    // The caller writes an object in whatever order reads well; the bytes must not care.
    const shuffled = {
      killSwitch: base.killSwitch,
      slippageCapBps: base.slippageCapBps,
      schema: base.schema,
      evidence: base.evidence,
      deskId: base.deskId,
      allowedVenues: base.allowedVenues,
      maxPositionUsd: base.maxPositionUsd,
      allowedModes: base.allowedModes,
      dailyLossLimitUsd: base.dailyLossLimitUsd,
      allowedAssets: base.allowedAssets,
      maxOpenPositions: base.maxOpenPositions,
    } as Policy;
    expect(serializePolicy(shuffled)).toBe(serializePolicy(base));
  });

  it("round-trips through the pre-check", () => {
    const bytes = serializePolicy(base);
    expect(() => precheckPolicyJson(bytes, "ebi")).not.toThrow();
  });
});

describe("validation rules the vectors do not cover", () => {
  function withEvidence(patch: Partial<EvidenceBlock>): unknown {
    return {
      schema: "krexa.ual.policy/1",
      deskId: "ebi",
      maxPositionUsd: "1000000000",
      maxOpenPositions: 3,
      dailyLossLimitUsd: "200000000",
      allowedAssets: ["BTC"],
      allowedVenues: ["paper"],
      slippageCapBps: 30,
      allowedModes: ["paper"],
      killSwitch: { autoOnDailyLoss: true, monitorMayEngage: true },
      evidence: {
        required: true,
        maxAgeSec: 900,
        groups: [{ group: "g1", sources: ["s1"] }],
        sizeTableBps: [0, 0, 5000, 10000],
        verifierCodeHash: "a".repeat(64),
        ...patch,
      },
    };
  }

  it("refuses a policy committed under the wrong desk", () => {
    expect(() => validatePolicy(withEvidence({}), "some-other-desk")).toThrowError(
      /does not match the desk being committed/,
    );
  });

  it("refuses maxAgeSec of 0 or above a day", () => {
    expect(() => validatePolicy(withEvidence({ maxAgeSec: 0 }), "ebi")).toThrow();
    expect(() => validatePolicy(withEvidence({ maxAgeSec: 86401 }), "ebi")).toThrow();
  });

  it("refuses a verifierCodeHash that is not 64 lowercase hex", () => {
    expect(() => validatePolicy(withEvidence({ verifierCodeHash: "A".repeat(64) }), "ebi")).toThrow();
    expect(() => validatePolicy(withEvidence({ verifierCodeHash: "ab" }), "ebi")).toThrow();
  });

  it("refuses duplicate group names", () => {
    expect(() =>
      validatePolicy(
        withEvidence({
          groups: [
            { group: "g1", sources: ["s1"] },
            { group: "g1", sources: ["s2"] },
          ],
        }),
        "ebi",
      ),
    ).toThrowError(/duplicate group/);
  });

  it("refuses a group with no sources", () => {
    expect(() => validatePolicy(withEvidence({ groups: [{ group: "g1", sources: [] }] }), "ebi")).toThrow();
  });

  it("refuses an unsorted venue set", () => {
    const p = {
      schema: "krexa.ual.policy/1",
      deskId: "ebi",
      maxPositionUsd: "1000000000",
      maxOpenPositions: 3,
      dailyLossLimitUsd: "200000000",
      allowedAssets: ["BTC"],
      allowedVenues: ["paper", "hyperliquid"],
      slippageCapBps: 30,
      allowedModes: ["paper"],
      killSwitch: { autoOnDailyLoss: true, monitorMayEngage: true },
    };
    expect(() => validatePolicy(p, "ebi")).toThrowError(/sorted and deduplicated/);
  });

  it("refuses an amount with a leading zero", () => {
    const p = {
      schema: "krexa.ual.policy/1",
      deskId: "ebi",
      maxPositionUsd: "0100000000",
      maxOpenPositions: 3,
      dailyLossLimitUsd: "200000000",
      allowedAssets: ["BTC"],
      allowedVenues: ["paper"],
      slippageCapBps: 30,
      allowedModes: ["paper"],
      killSwitch: { autoOnDailyLoss: true, monitorMayEngage: true },
    };
    expect(() => validatePolicy(p, "ebi")).toThrowError(/leading zero/);
  });
});

describe("size table reading matches the contract", () => {
  const ev: EvidenceBlock = {
    required: true,
    maxAgeSec: 900,
    groups: [
      { group: "exchange-hl", sources: ["hyperliquid"] },
      { group: "newswire-a", sources: ["newswire-a.example"] },
    ],
    sizeTableBps: [0, 0, 5000, 10000],
    verifierCodeHash: "a".repeat(64),
  };

  it("sizes k=0 and k=1 to nothing, k=2 to half, k=3 to full", () => {
    expect(sizeMultiplierBps(ev, 0)).toBe(0);
    expect(sizeMultiplierBps(ev, 1)).toBe(0);
    expect(sizeMultiplierBps(ev, 2)).toBe(5000);
    expect(sizeMultiplierBps(ev, 3)).toBe(10000);
  });

  it("reuses the last entry past the end of the table", () => {
    // k = 9 independent groups is still full size, not an index error.
    expect(sizeMultiplierBps(ev, 9)).toBe(10000);
  });

  it("reports the first k that earns a non-zero size", () => {
    expect(minKForNonZero(ev)).toBe(2);
    expect(minKForNonZero({ ...ev, sizeTableBps: [0, 0, 0, 0] })).toBeUndefined();
  });

  it("resolves a declared source and refuses to guess at an undeclared one", () => {
    expect(groupForSource(ev, "hyperliquid")).toBe("exchange-hl");
    // Fail closed: an undeclared source buys no corroboration.
    expect(groupForSource(ev, "random-blog.example")).toBeUndefined();
  });
});
